mapper.insert:
INSERT INTO transaction_records (
    wallet_id, type, amount, balance_after, 
    payment_method, bank_card_number, payee_id, 
    transaction_time, remark
) VALUES (
    #{walletId}, #{type}, #{amount}, #{balanceAfter}, 
    #{paymentMethod}, #{bankCardNumber}, #{payeeId}, 
    NOW(), #{remark}
)

mapper.select:
SELECT 
    id, wallet_id, type, amount, balance_after, 
    payment_method, bank_card_number, payee_id, 
    transaction_time, remark
FROM transaction_records
WHERE wallet_id = #{walletId}

    AND type = #{params.type}


    AND transaction_time >= #{params.startTime}


    AND transaction_time <= #{params.endTime}

ORDER BY transaction_time DESC

    LIMIT #{params.offset}, #{params.limit}

SELECT COUNT(*)
FROM transaction_records
WHERE wallet_id = #{walletId}

    AND type = #{params.type}


    AND transaction_time >= #{params.startTime}


    AND transaction_time <= #{params.endTime}
